"""User-facing status text; stable machine codes remain in diagnostic evidence."""
LABELS={'WAITING':'等待執行','RUNNING':'執行中，尚未完成','PAUSED_RESOURCES':'資源暫停','INTERRUPTED':'中斷，待明確恢復','BLOCKED':'例外待處理','DONE':'執行結果已保存','CANCELLED':'已取消','CANCELLED_BEFORE_CLAIM':'已取消尚未啟動的範圍','CONTINUATION_PENDING':'故障項已隔離，其餘待續跑','COMPLETED':'執行完成','COMPLETED_WITH_EXCEPTIONS':'執行完成，待審／例外另計','FAILED_SYSTEM':'保存／系統故障','PENDING_ANALYSIS':'待分析，作品覆蓋尚未知','OPEN_WORKS_FOR_CURRENT_VALIDITY':'查看作品以核實狀態','WAITING_REVIEW':'分析後待人工審核','VERIFIED_REUSABLE_ANALYSIS':'已核實可重用分析快取','STALE_ANALYSIS_REQUIRES_RECHECK':'分析依據已失效，待重核','CONFIRMED':'已核實人工確認','STALE_REVIEW':'原審核已失效，需重新核對','WAITING_HUMAN_REVIEW':'待人工審核','EXPLICITLY_EXCLUDED':'已明確排除（另計）','EXCLUDED':'已排除紀錄','FAILED':'失敗／例外待處理','BACKGROUND_PAUSED_BY_OPERATOR':'已暫停背景工作','RESOURCE_SAMPLE_PENDING':'等待資源取樣','GUI_STARTUP_WARMUP':'介面啟動暖機','MEMORY_PRESSURE':'記憶體壓力','CPU_PRESSURE':'處理器壓力','IO_WAIT_PRESSURE':'磁碟I/O等待偏高','DISK_HEADROOM_LOW':'可寫磁碟空間不足','GUI_HEARTBEAT_LATE':'優先讓介面回應','FOREGROUND_INTERACTION_PRIORITY':'優先目前前景操作','RECOVERY_HYSTERESIS':'等待穩定取樣後恢復'}


def label(value):return '、'.join(LABELS.get(part,part) for part in str(value).split(','))
